    document.body.removeChild(ta);
    return ok;
  }
  function done(btn,ok){
    var label=btn.querySelector("span");
    label.textContent=ok?"Đã chép":"Không chép được";
    btn.classList.toggle("ok",ok);
    clearTimeout(btn._t);
    btn._t=setTimeout(function(){label.textContent="Sao chép";btn.classList.remove("ok")},1800);
  }
  Array.prototype.forEach.call(document.querySelectorAll(".copy"),function(btn){
    btn.addEventListener("click",function(){
      var el=document.getElementById(btn.getAttribute("data-copy"));
      var text=el?el.textContent.replace(/\s+$/,""):"";
      if(navigator.clipboard&&window.isSecureContext){
        navigator.clipboard.writeText(text).then(function(){done(btn,true)},function(){done(btn,fallbackCopy(text))});
      }else{
        done(btn,fallbackCopy(text));
      }
    });
  });
})();
</script>
</body>
</html>
