1	<!doctype html>
2	<html lang="vi">
3	<head>
4	<meta charset="utf-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1">
6	<title>Pentagon — 1 người giao việc, 1 AI quản lý, nhiều AI làm</title>
7	<meta name="description" content="Pentagon biến các gói thuê bao AI bạn đã trả tiền (Claude, ChatGPT, Google AI) thành một đội làm việc: 1 AI quản lý chia việc cho nhiều AI worker, tự chuyển tài khoản khi hết hạn mức. Không cần API key, chạy trên máy của bạn.">
8	<meta name="theme-color" content="#f6f7f9" media="(prefers-color-scheme: light)">
9	<meta name="theme-color" content="#121417" media="(prefers-color-scheme: dark)">
10	<meta property="og:type" content="website">
11	<meta property="og:title" content="Pentagon — 1 người giao việc, 1 AI quản lý, nhiều AI làm">
12	<meta property="og:description" content="Tận dụng gói Claude, ChatGPT, Google AI bạn đã có: 1 AI quản lý chia việc, nhiều AI worker làm, tự chuyển tài khoản khi hết hạn mức. Không cần API key.">
13	<meta property="og:image" content="img/og.png">
14	<meta property="og:image:width" content="1200">
15	<meta property="og:image:height" content="630">
16	<meta name="twitter:card" content="summary_large_image">
17	<meta name="twitter:title" content="Pentagon — 1 người giao việc, 1 AI quản lý, nhiều AI làm">
18	<meta name="twitter:description" content="Một đội AI làm việc cho bạn, chạy trên máy của bạn, dùng gói thuê bao sẵn có.">
19	<meta name="twitter:image" content="img/og.png">
20	<link rel="icon" type="image/svg+xml" href="img/favicon.svg">
21	<link rel="apple-touch-icon" href="img/mark.png">
22	<style>
23	:root{
24	  --bg:#f6f7f9;--panel:#fff;--line:#e3e6ea;--text:#1d2228;--muted:#69727d;--soft:#f0f2f5;
25	  --accent:#3b6fd8;--ok:#1f9d55;--warn:#c58a00;--bad:#d64545;--run:#0e8fa6;--mgr:#8a4fd1;
26	  --shadow:0 1px 2px rgba(16,24,40,.05),0 8px 24px rgba(16,24,40,.07);
27	  --shadow-lg:0 2px 4px rgba(16,24,40,.06),0 24px 48px rgba(16,24,40,.12);
28	  --frame:#fff;--img-filter:none;
29	  --font:-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,sans-serif;
30	  --mono:ui-monospace,Menlo,Consolas,monospace;
31	  color-scheme:light;
32	}
33	@media (prefers-color-scheme: dark){
34	  :root:not([data-theme="light"]){
35	    --bg:#121417;--panel:#1a1d21;--line:#2b3036;--text:#e6e8eb;--muted:#9099a3;--soft:#22262b;
36	    --accent:#6f9bff;--ok:#3ccf7f;--warn:#f0b429;--bad:#ff6b6b;--run:#3cc7de;--mgr:#b98aff;
37	    --shadow:0 1px 2px rgba(0,0,0,.3),0 8px 24px rgba(0,0,0,.35);
38	    --shadow-lg:0 2px 4px rgba(0,0,0,.3),0 24px 48px rgba(0,0,0,.45);
39	    --frame:#22262b;--img-filter:brightness(.88) contrast(1.02);
40	    color-scheme:dark;
41	  }
42	}
43	:root[data-theme="dark"]{
44	  --bg:#121417;--panel:#1a1d21;--line:#2b3036;--text:#e6e8eb;--muted:#9099a3;--soft:#22262b;
45	  --accent:#6f9bff;--ok:#3ccf7f;--warn:#f0b429;--bad:#ff6b6b;--run:#3cc7de;--mgr:#b98aff;
46	  --shadow:0 1px 2px rgba(0,0,0,.3),0 8px 24px rgba(0,0,0,.35);
47	  --shadow-lg:0 2px 4px rgba(0,0,0,.3),0 24px 48px rgba(0,0,0,.45);
48	  --frame:#22262b;--img-filter:brightness(.88) contrast(1.02);
49	  color-scheme:dark;
50	}
51	*{box-sizing:border-box}
52	html{scroll-behavior:smooth;scroll-padding-top:76px;-webkit-text-size-adjust:100%}
53	@media (prefers-reduced-motion: reduce){html{scroll-behavior:auto}*{transition:none!important;animation:none!important}}
54	body{margin:0;background:var(--bg);color:var(--text);font-family:var(--font);font-size:16px;line-height:1.6;overflow-x:hidden}
55	img{max-width:100%;height:auto;display:block}
56	a{color:var(--accent);text-decoration:none}
57	a:hover{text-decoration:underline}
58	code,kbd,pre{font-family:var(--mono)}
59	code{font-size:.9em;background:var(--soft);border:1px solid var(--line);border-radius:6px;padding:.08em .38em;overflow-wrap:anywhere}
60	h1,h2,h3{line-height:1.2;margin:0;letter-spacing:-.01em}
61	p{margin:0}
62	.wrap{max-width:1100px;margin:0 auto;padding:0 24px}
63	@media (max-width:600px){.wrap{padding:0 16px}}
64	.sr-only{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap}
65	
66	/* ---------- topbar ---------- */
67	.top{position:sticky;top:0;z-index:50;background:color-mix(in srgb,var(--bg) 82%,transparent);backdrop-filter:saturate(1.4) blur(12px);-webkit-backdrop-filter:saturate(1.4) blur(12px);border-bottom:1px solid var(--line)}
68	.top .wrap{display:flex;align-items:center;gap:16px;height:60px}
69	.brand{display:flex;align-items:center;gap:10px;font-weight:750;font-size:18px;color:var(--text)}
70	.brand:hover{text-decoration:none}
71	.brand img{width:32px;height:28px}
72	.nav{display:flex;gap:4px;margin-left:auto}
73	.nav a{color:var(--muted);font-size:14.5px;padding:6px 10px;border-radius:8px}
74	.nav a:hover{color:var(--text);background:var(--soft);text-decoration:none}
75	.top-actions{display:flex;align-items:center;gap:8px}
76	.icon-btn{width:38px;height:38px;border-radius:10px;border:1px solid var(--line);background:var(--panel);color:var(--text);display:grid;place-items:center;cursor:pointer}
77	.icon-btn:hover{background:var(--soft)}
78	.icon-btn svg{width:18px;height:18px}
79	.icon-btn .sun{display:none}
80	:root[data-theme-now="dark"] .icon-btn .sun{display:block}
81	:root[data-theme-now="dark"] .icon-btn .moon{display:none}
82	@media (max-width:900px){.nav{display:none}.top-actions{margin-left:auto}}
83	
84	/* ---------- buttons ---------- */
85	.btn{display:inline-flex;align-items:center;justify-content:center;gap:8px;font:inherit;font-weight:650;font-size:15.5px;line-height:1;padding:14px 22px;border-radius:12px;border:1px solid transparent;cursor:pointer;white-space:nowrap;transition:transform .15s ease,box-shadow .15s ease,background .15s}
86	.btn:hover{text-decoration:none;transform:translateY(-1px)}
87	.btn-primary{background:var(--accent);color:#fff;box-shadow:0 6px 18px color-mix(in srgb,var(--accent) 35%,transparent)}
88	.btn-primary:hover{box-shadow:0 10px 26px color-mix(in srgb,var(--accent) 45%,transparent)}
89	:root[data-theme-now="dark"] .btn-primary{color:#0d1424}
90	.btn-ghost{background:var(--panel);color:var(--text);border-color:var(--line)}
91	.btn-ghost:hover{background:var(--soft)}
92	.btn-sm{padding:10px 14px;font-size:14px;border-radius:10px}
93	.btn svg{width:16px;height:16px}
94	@media (max-width:420px){.top .btn-sm{padding:10px 12px}}
95	
96	/* ---------- hero ---------- */
97	.hero{position:relative;padding:72px 0 56px;overflow:hidden}
98	.hero::before{content:"";position:absolute;inset:-20% -10% auto -10%;height:120%;z-index:-1;
99	  background:radial-gradient(600px 360px at 18% 20%,color-mix(in srgb,var(--mgr) 16%,transparent),transparent 70%),
100	             radial-gradient(640px 400px at 85% 40%,color-mix(in srgb,var(--accent) 16%,transparent),transparent 70%)}
101	.hero-grid{display:grid;grid-template-columns:1.02fr 1fr;gap:48px;align-items:center}
102	.eyebrow{display:inline-flex;align-items:center;gap:8px;font-size:13.5px;font-weight:650;color:var(--mgr);background:color-mix(in srgb,var(--mgr) 10%,var(--panel));border:1px solid color-mix(in srgb,var(--mgr) 28%,var(--line));padding:6px 12px;border-radius:999px}
103	.eyebrow .dot{width:8px;height:8px;border-radius:50%;background:var(--mgr)}
104	.hero h1{font-size:clamp(34px,5.4vw,58px);font-weight:800;margin:18px 0 18px;letter-spacing:-.025em}
105	.hero h1 .mgr{color:var(--mgr)}
106	.hero h1 .wk{color:var(--accent)}
107	.lead{font-size:clamp(17px,1.9vw,19.5px);color:var(--muted);max-width:560px}
108	.lead strong{color:var(--text)}
109	.cta-row{display:flex;flex-wrap:wrap;gap:12px;margin-top:28px}
110	.checks{list-style:none;padding:0;margin:26px 0 0;display:flex;flex-wrap:wrap;gap:8px 18px;color:var(--muted);font-size:14.5px}
111	.checks li{display:flex;align-items:center;gap:7px}
112	.checks svg{width:16px;height:16px;color:var(--ok);flex:none}
113	.frame{background:var(--frame);border:1px solid var(--line);border-radius:22px;padding:10px;box-shadow:var(--shadow-lg)}
114	.frame img{border-radius:14px;filter:var(--img-filter);width:100%}
115	.hero .frame{transform:rotate(.6deg)}
116	@media (max-width:900px){
117	  .hero{padding:44px 0 36px}
118	  .hero-grid{grid-template-columns:1fr;gap:32px}
119	  .hero .frame{transform:none;max-width:560px;margin:0 auto;width:100%}
120	}
121	@media (max-width:420px){.cta-row .btn{flex:1 1 100%}}
122	
123	/* ---------- sections ---------- */
124	section{padding:72px 0}
125	@media (max-width:600px){section{padding:52px 0}}
126	.sec-head{max-width:700px;margin:0 auto 40px;text-align:center}
127	.kicker{font-size:13px;font-weight:700;letter-spacing:.08em;text-transform:uppercase;color:var(--accent)}
128	.sec-head h2{font-size:clamp(27px,3.6vw,40px);font-weight:800;margin:10px 0 12px;letter-spacing:-.02em}
129	.sec-head p{color:var(--muted);font-size:17px}
130	.alt{background:var(--panel);border-top:1px solid var(--line);border-bottom:1px solid var(--line)}
131	
132	/* ---------- benefits ---------- */
133	.benefits{display:grid;grid-template-columns:repeat(4,1fr);gap:16px}
134	.benefit{background:var(--panel);border:1px solid var(--line);border-radius:16px;padding:22px;box-shadow:var(--shadow)}
135	.benefit .ic{width:40px;height:40px;border-radius:11px;display:grid;place-items:center;margin-bottom:14px;color:#fff}
136	.benefit .ic svg{width:21px;height:21px}
137	.benefit h3{font-size:17px;margin-bottom:6px}
138	.benefit p{color:var(--muted);font-size:15px}
139	.i-mgr{background:linear-gradient(135deg,#b98aff,#8a4fd1)}
140	.i-acc{background:linear-gradient(135deg,#6f9bff,#3b6fd8)}
141	.i-ok{background:linear-gradient(135deg,#3ccf7f,#1f9d55)}
142	.i-run{background:linear-gradient(135deg,#3cc7de,#0e8fa6)}
143	@media (max-width:960px){.benefits{grid-template-columns:repeat(2,1fr)}}
144	@media (max-width:560px){.benefits{grid-template-columns:1fr}}
145	
146	/* ---------- flow ---------- */
147	.node{background:var(--panel);border:1px solid var(--line);border-radius:16px;padding:16px 18px;box-shadow:var(--shadow);min-width:0}
148	.node .tag{font-size:12px;font-weight:700;text-transform:uppercase;letter-spacing:.06em;color:var(--muted)}
149	.node h3{font-size:16.5px;margin:4px 0 6px}
150	.node p{font-size:14px;color:var(--muted)}
151	.node.you{border-top:3px solid var(--text)}
152	.node.mgr{border-top:3px solid var(--mgr)}
153	.node.mgr h3{color:var(--mgr)}
154	.node.wk{border-top:3px solid var(--accent)}
155	.node.done{border-top:3px solid var(--ok)}
156	.arrow{display:flex;align-items:center;justify-content:center;color:var(--muted);font-family:var(--mono);font-size:12.5px;padding:0 8px;text-align:center;flex-direction:column;gap:2px}
157	.arrow svg{width:28px;height:14px}
158	.flow-wrap{display:grid;grid-template-columns:1fr 30px 1.15fr 30px 1.25fr 30px 1fr;align-items:center}
159	.lanes{display:grid;gap:8px}
160	.lane{display:flex;flex-wrap:wrap;align-items:center;gap:4px 6px;font-family:var(--mono);font-size:12.5px;background:var(--soft);border:1px solid var(--line);border-radius:10px;padding:7px 10px}
161	.lane b{color:var(--accent);font-weight:700}
162	.lane .sep{color:var(--muted)}
163	.flow-note{margin-top:18px;text-align:center;color:var(--muted);font-size:14.5px}
164	@media (max-width:900px){
165	  .flow-wrap{grid-template-columns:1fr}
166	  .flow-wrap .arrow{transform:rotate(90deg);height:30px}
167	}
168	
169	/* ---------- feature rows ---------- */
170	.feature{display:grid;grid-template-columns:1fr 1fr;gap:56px;align-items:center;padding:36px 0}
171	.feature + .feature{border-top:1px dashed var(--line)}
172	.feature.rev .f-media{order:2}
173	.f-badge{display:inline-flex;align-items:center;gap:8px;font-size:13px;font-weight:700;color:var(--accent);letter-spacing:.04em;text-transform:uppercase}
174	.f-badge .n{width:24px;height:24px;border-radius:7px;display:grid;place-items:center;background:color-mix(in srgb,var(--accent) 14%,var(--panel));font-size:12.5px}
175	.feature h3{font-size:clamp(23px,2.8vw,31px);font-weight:800;margin:10px 0 12px;letter-spacing:-.015em}
176	.feature .desc{color:var(--muted);font-size:16.5px}
177	.ticks{list-style:none;padding:0;margin:18px 0 0;display:grid;gap:10px}
178	.ticks li{display:grid;grid-template-columns:20px 1fr;gap:10px;font-size:15.5px}
179	.ticks svg{width:18px;height:18px;color:var(--ok);margin-top:3px}
180	.f-link{display:inline-flex;align-items:center;gap:6px;margin-top:20px;font-weight:650}
181	.f-link svg{width:16px;height:16px}
182	.caption{margin-top:10px;text-align:center;font-size:13px;color:var(--muted)}
183	.size-pills{display:flex;flex-wrap:wrap;gap:8px;margin-top:16px}
184	.pill{font-family:var(--mono);font-size:13.5px;border:1px solid var(--line);background:var(--soft);border-radius:999px;padding:5px 12px}
185	.pill b{color:var(--accent)}
186	@media (max-width:860px){
187	  .feature{grid-template-columns:1fr;gap:24px;padding:28px 0}
188	  .feature.rev .f-media{order:0}
189	  .f-media{max-width:560px;width:100%;margin:0 auto}
190	}
191	.mini{display:grid;grid-template-columns:1fr 1fr;gap:16px;margin-top:28px}
192	.mini .benefit h3{font-size:18px}
193	@media (max-width:700px){.mini{grid-template-columns:1fr}}
194	
195	/* ---------- CTA band ---------- */
196	.band{position:relative;border-radius:24px;padding:40px;overflow:hidden;color:#fff;
197	  background:linear-gradient(120deg,#6b3fb8 0%,#3b6fd8 60%,#0e8fa6 120%);box-shadow:var(--shadow-lg);
198	  display:flex;align-items:center;justify-content:space-between;gap:24px;flex-wrap:wrap}
199	.band h2{font-size:clamp(23px,3vw,32px);font-weight:800;letter-spacing:-.015em}
200	.band p{opacity:.9;margin-top:8px;max-width:560px}
201	.band .btn-primary{background:#fff;color:#2a3a70;box-shadow:0 8px 22px rgba(0,0,0,.2)}
202	:root[data-theme-now="dark"] .band .btn-primary{color:#2a3a70}
203	.band .btn-ghost{background:transparent;color:#fff;border-color:rgba(255,255,255,.45)}
204	.band .btn-ghost:hover{background:rgba(255,255,255,.12)}
205	.band-actions{display:flex;gap:12px;flex-wrap:wrap}
206	@media (max-width:600px){.band{padding:28px 22px}.band-actions{width:100%}.band-actions .btn{flex:1 1 100%}}
207	
208	/* ---------- steps ---------- */
209	.steps{display:grid;grid-template-columns:repeat(3,1fr);gap:16px;counter-reset:s}
210	.step{position:relative;background:var(--panel);border:1px solid var(--line);border-radius:16px;padding:22px 22px 22px 22px;box-shadow:var(--shadow)}
211	.step .num{width:36px;height:36px;border-radius:50%;display:grid;place-items:center;font-weight:800;color:#fff;background:linear-gradient(135deg,#b98aff,#8a4fd1);margin-bottom:12px}
212	.step:last-child .num{background:linear-gradient(135deg,#3ccf7f,#1f9d55)}
213	.step h3{font-size:17px;margin-bottom:6px}
214	.step p{font-size:15px;color:var(--muted)}
215	@media (max-width:900px){.steps{grid-template-columns:repeat(2,1fr)}}
216	@media (max-width:560px){.steps{grid-template-columns:1fr}}
217	
218	/* ---------- workers ---------- */
219	.workers{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}
220	.worker{background:var(--panel);border:1px solid var(--line);border-radius:16px;padding:22px;box-shadow:var(--shadow);border-top:3px solid var(--accent)}
221	.worker .name{font-family:var(--mono);font-weight:700;font-size:18px;color:var(--accent)}
222	.worker .role{font-size:13px;color:var(--muted);margin:2px 0 12px}
223	.worker p{font-size:15px}
224	.worker .acc{margin-top:14px;font-family:var(--mono);font-size:12.5px;color:var(--muted);display:flex;flex-wrap:wrap;gap:6px}
225	.worker .acc span{background:var(--soft);border:1px solid var(--line);border-radius:6px;padding:2px 8px}
226	@media (max-width:800px){.workers{grid-template-columns:1fr}}
227	
228	/* ---------- quick start ---------- */
229	.qs{display:grid;grid-template-columns:1.35fr 1fr;gap:24px;align-items:start}
230	.qs>*,.flow-wrap>*,.hero-grid>*,.feature>*{min-width:0}
231	.code{position:relative;background:#0f1216;color:#dfe4ea;border:1px solid #262b31;border-radius:16px;box-shadow:var(--shadow-lg);overflow:hidden}
232	.code-head{display:flex;align-items:center;justify-content:space-between;gap:8px;padding:10px 12px 10px 16px;border-bottom:1px solid #262b31;background:#151a20}
233	.code-head .dots{display:flex;gap:6px}
234	.code-head .dots i{width:10px;height:10px;border-radius:50%;background:#3a4048;display:block}
235	.code-head .t{font-size:12.5px;color:#8b95a1;font-family:var(--mono);margin-right:auto;margin-left:8px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
236	.copy{font:inherit;font-size:13px;font-weight:650;color:#dfe4ea;background:#232a33;border:1px solid #333b45;border-radius:8px;padding:6px 12px;cursor:pointer;display:inline-flex;align-items:center;gap:6px;flex:none}
237	.copy:hover{background:#2c3540}
238	.copy.ok{color:#3ccf7f;border-color:#2c6b4a}
239	.copy svg{width:14px;height:14px}
240	.code pre{margin:0;padding:18px 18px 20px;font-size:13.5px;line-height:1.75;overflow-x:auto;white-space:pre}
241	.code .c{color:#7d8794}
242	.code .p{color:#b98aff;user-select:none}
243	.code .s{color:#9fd3a8}
244	.code .k{color:#6f9bff}
245	.side{display:grid;gap:16px}
246	.card{background:var(--panel);border:1px solid var(--line);border-radius:16px;padding:20px;box-shadow:var(--shadow)}
247	.card h3{font-size:16.5px;margin-bottom:8px}
248	.card p,.card li{font-size:15px;color:var(--muted)}
249	.card ul{margin:0;padding-left:18px;display:grid;gap:4px}
250	.card + .card{margin-top:0}
251	.code.small pre{font-size:13px}
252	@media (max-width:900px){.qs{grid-template-columns:1fr}}
253	@media (max-width:600px){.code pre{font-size:12.5px;padding:14px}}
254	
255	/* ---------- where ---------- */
256	.where{background:var(--panel);border:1px solid var(--line);border-radius:16px;box-shadow:var(--shadow);overflow:hidden}
257	.where table{width:100%;border-collapse:collapse;font-size:15px}
258	.where th,.where td{text-align:left;padding:14px 18px;border-bottom:1px solid var(--line);vertical-align:top}
259	.where th{font-size:13px;text-transform:uppercase;letter-spacing:.05em;color:var(--muted);background:var(--soft);font-weight:700}
260	.where tr:last-child td{border-bottom:0}
261	.where td:first-child{font-weight:650;width:34%}
262	.where td:nth-child(2){width:72px;text-align:center}
263	.yes,.no{display:inline-grid;place-items:center;width:26px;height:26px;border-radius:50%;color:#fff}
264	.yes{background:var(--ok)}.no{background:var(--bad)}
265	.yes svg,.no svg{width:14px;height:14px}
266	:root[data-theme-now="dark"] .yes,:root[data-theme-now="dark"] .no{color:#121417}
267	.where-note{margin-top:14px;color:var(--muted);font-size:14.5px;text-align:center}
268	@media (max-width:600px){
269	  .where th,.where td{padding:12px 12px;font-size:14px}
270	  .where td:first-child{width:auto}
271	  .where td:nth-child(2){width:44px}
272	}
273	
274	/* ---------- faq ---------- */
275	.faq{max-width:780px;margin:0 auto;display:grid;gap:12px}
276	.faq details{background:var(--panel);border:1px solid var(--line);border-radius:14px;box-shadow:var(--shadow)}
277	.faq summary{cursor:pointer;list-style:none;padding:18px 52px 18px 20px;font-weight:650;font-size:16.5px;position:relative}
278	.faq summary::-webkit-details-marker{display:none}
279	.faq summary::after{content:"";position:absolute;right:22px;top:50%;width:9px;height:9px;border-right:2px solid var(--muted);border-bottom:2px solid var(--muted);transform:translateY(-70%) rotate(45deg);transition:transform .2s}
280	.faq details[open] summary::after{transform:translateY(-30%) rotate(-135deg)}
281	.faq .ans{padding:0 20px 18px;color:var(--muted);font-size:15.5px}
282	
283	/* ---------- footer ---------- */
284	footer{border-top:1px solid var(--line);padding:32px 0 40px;color:var(--muted);font-size:14.5px}
285	footer .wrap{display:flex;align-items:center;gap:12px;flex-wrap:wrap;justify-content:space-between}
286	footer .brand{font-size:15px}
287	footer .brand img{width:26px;height:23px}
