836	<script>
837	/* Hiệu ứng cuộn: hiện dần, thanh tiến trình, đánh dấu mục nav */
838	(function(){
839	  var root=document.documentElement;
840	  try{
841	    var top=document.querySelector(".top"),bar=document.getElementById("progress");
842	    var links=Array.prototype.slice.call(document.querySelectorAll(".nav a"));
843	    var secs=Array.prototype.slice.call(document.querySelectorAll("main section[id]"));
844	    var pending=[];
845	    function reveal(el){
846	      if(el._shown)return;el._shown=true;
847	      el.classList.add("in");
848	      var d=parseFloat(el.style.transitionDelay)||0;
849	      setTimeout(function(){
850	        el.classList.remove("rv","rv-l","rv-r","in");el.style.transitionDelay="";
851	      },d*1000+900);
852	    }
853	    if(root.classList.contains("js-anim")){
854	      var counts=new Map();
855	      var add=function(el,dir,delay){
856	        el.classList.add("rv");if(dir)el.classList.add(dir);
857	        if(delay)el.style.transitionDelay=delay+"s";
858	        pending.push(el);
859	      };
860	      var group=function(sel){
861	        Array.prototype.forEach.call(document.querySelectorAll(sel),function(el){
862	          var p=el.parentNode,m=counts.get(p);
863	          if(!m){m={};counts.set(p,m)}
864	          var n=m[sel]||0;m[sel]=n+1;
865	          add(el,"",Math.min(n,6)*0.09);
866	        });
867	      };
868	      [".sec-head",".benefit",".node",".lane",".step",".worker",".card",".where",".faq details",".band"].forEach(group);
869	      Array.prototype.forEach.call(document.querySelectorAll(".feature"),function(f){
870	        var media=f.querySelector(".f-media"),text=media&&media.nextElementSibling;
871	        var rev=f.classList.contains("rev");
872	        if(media)add(media,rev?"rv-r":"rv-l",0);
873	        if(text)add(text,rev?"rv-l":"rv-r",0.12);
874	      });
875	      var io=new IntersectionObserver(function(es){
876	        es.forEach(function(e){
877	          if(e.isIntersecting||e.boundingClientRect.top<0){io.unobserve(e.target);reveal(e.target)}
878	        });
879	      },{threshold:0.12,rootMargin:"0px 0px -6% 0px"});
880	      pending.forEach(function(el){io.observe(el)});
881	    }
882	    var ticking=false;
883	    function update(){
884	      ticking=false;
885	      var y=window.pageYOffset||root.scrollTop,max=root.scrollHeight-window.innerHeight;
886	      if(bar)bar.style.transform="scaleX("+(max>0?Math.min(1,Math.max(0,y/max)):0)+")";
887	      top.classList.toggle("scrolled",y>8);
888	      var cur="";
889	      secs.forEach(function(s){if(s.getBoundingClientRect().top<=120)cur=s.id});
890	      links.forEach(function(a){
891	        var on=a.getAttribute("href")==="#"+cur;
892	        a.classList.toggle("active",on);
893	        if(on)a.setAttribute("aria-current","true");else a.removeAttribute("aria-current");
894	      });
895	      for(var i=pending.length-1;i>=0;i--){
896	        var el=pending[i];
897	        if(el._shown){pending.splice(i,1);continue}
898	        if(el.getBoundingClientRect().bottom<0){reveal(el);pending.splice(i,1)}
899	      }
900	    }
901	    function onScroll(){if(!ticking){ticking=true;requestAnimationFrame(update)}}
902	    window.addEventListener("scroll",onScroll,{passive:true});
903	    window.addEventListener("resize",onScroll);
904	    update();
905	  }catch(err){
906	    root.classList.remove("js-anim");
907	    Array.prototype.forEach.call(document.querySelectorAll(".rv"),function(e){e.classList.remove("rv","rv-l","rv-r")});
908	  }
909	})();
910	</script>
911	</body>
912	</html>
